create extension if not exists pgcrypto;
create table public.perfiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,nombre text default '',rol text not null default 'cajero' check(rol in('superadmin','cajero')));
create table public.productos(id uuid primary key default gen_random_uuid(),nombre text not null,categoria text not null default 'Café',descripcion text default '',precio numeric(10,2) not null check(precio>=0),stock_actual integer not null default 0,stock_minimo integer not null default 0,disponible boolean not null default true,temporada boolean not null default false,created_at timestamptz default now());
create table public.proveedores(id uuid primary key default gen_random_uuid(),nombre text not null,telefono text default '',contacto text default '',activo boolean default true);
create table public.trabajadores(id uuid primary key default gen_random_uuid(),nombre text not null,email text default '',cargo text default '',sueldo numeric(10,2) default 0,activo boolean default true);
create table public.movimientos_financieros(id uuid primary key default gen_random_uuid(),tipo text not null check(tipo in('ingreso','egreso')),concepto text not null,monto numeric(10,2) not null check(monto>0),fecha date not null default current_date,created_at timestamptz default now(),creado_por uuid default auth.uid());
create table public.ventas(id uuid primary key default gen_random_uuid(),total numeric(10,2) not null default 0,metodo_pago text default 'efectivo',estado text default 'completada',creado_por uuid default auth.uid(),created_at timestamptz default now());
alter table public.perfiles enable row level security;alter table public.productos enable row level security;alter table public.proveedores enable row level security;alter table public.trabajadores enable row level security;alter table public.movimientos_financieros enable row level security;alter table public.ventas enable row level security;
create or replace function public.is_superadmin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.perfiles where id=auth.uid() and rol='superadmin')$$;
create policy perfiles_self on public.perfiles for select using(id=auth.uid());create policy productos_equipo_lectura on public.productos for select using(auth.uid() is not null);create policy productos_admin on public.productos for all using(public.is_superadmin()) with check(public.is_superadmin());
create policy proveedores_admin on public.proveedores for all using(public.is_superadmin()) with check(public.is_superadmin());create policy trabajadores_admin on public.trabajadores for all using(public.is_superadmin()) with check(public.is_superadmin());create policy finanzas_admin on public.movimientos_financieros for all using(public.is_superadmin()) with check(public.is_superadmin());create policy ventas_equipo on public.ventas for select using(auth.uid() is not null);create policy ventas_cajero on public.ventas for insert with check(auth.uid() is not null);
create or replace function public.crear_perfil_harvest() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.perfiles(id,email,nombre,rol) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'nombre',''),case when lower(new.email)=lower(coalesce(current_setting('app.harvest_superadmin_email',true),'')) then 'superadmin' else 'cajero' end);return new;end$$;
create trigger crear_perfil_harvest after insert on auth.users for each row execute function public.crear_perfil_harvest();
insert into public.productos(nombre,categoria,descripcion,precio,stock_actual,stock_minimo) values('Flat white','Café','Espresso doble y leche texturizada.',12,20,5),('Cold brew','Café','Café de extracción lenta.',14,15,4),('Panini caprese','Brunch','Pan artesanal, mozzarella y pesto.',19,10,3),('Pancakes de frutos','Brunch','Fruta fresca, yogurt y miel.',22,12,3),('Keke de plátano','Dulces','Horneado en casa.',10,8,2);
